// Provided for lab 8.1 (you do not edit this file): the shared-memory tiled stencil
// of book Fig. 8.8 (section 8.4, p. 191), used as a benchmark comparison.
//
// Each block is a cube of CUBE_IN_TILE_DIM^3 threads. Every thread loads one input
// element into shared memory; after one barrier the inner (CUBE_IN_TILE_DIM - 2)^3
// threads compute the output tile from shared memory.
//
// Differs from the page:
//   - The tile is fixed at 8 (512 threads), the book's "practical limit" (p. 192), and
//     its constants are named CUBE_* so that they cannot clash with the lab's
//     IN_TILE_DIM. The listing uses IN_TILE_DIM and OUT_TILE_DIM without defining them.
//   - `in` is const and the weights arrive as one StencilCoeffs argument; the listing
//     leaves c0..c6 undeclared.
//   - The launch function is ours (the book shows no host code).
#include "../lab1_stencil3d/stencil.h"

#define CUBE_IN_TILE_DIM 8
#define CUBE_OUT_TILE_DIM (CUBE_IN_TILE_DIM - 2)

__global__ void stencilTiledCubeKernel(const float* in, float* out, unsigned int N, StencilCoeffs c) {
    // The "- 1" is the stencil order: block b's input tile starts one point before
    // its output tile (p. 191).
    int i = blockIdx.z * CUBE_OUT_TILE_DIM + threadIdx.z - 1;
    int j = blockIdx.y * CUBE_OUT_TILE_DIM + threadIdx.y - 1;
    int k = blockIdx.x * CUBE_OUT_TILE_DIM + threadIdx.x - 1;
    __shared__ float in_s[CUBE_IN_TILE_DIM][CUBE_IN_TILE_DIM][CUBE_IN_TILE_DIM];
    if (i >= 0 && i < N && j >= 0 && j < N && k >= 0 && k < N) {
        in_s[threadIdx.z][threadIdx.y][threadIdx.x] = in[i * N * N + j * N + k];
    }
    __syncthreads();
    // Two separate guards: the grid's boundary layer is never computed, and the
    // threads on the cube's surface only loaded.
    if (i >= 1 && i < N - 1 && j >= 1 && j < N - 1 && k >= 1 && k < N - 1) {
        if (threadIdx.z >= 1 && threadIdx.z < CUBE_IN_TILE_DIM - 1 &&
            threadIdx.y >= 1 && threadIdx.y < CUBE_IN_TILE_DIM - 1 &&
            threadIdx.x >= 1 && threadIdx.x < CUBE_IN_TILE_DIM - 1) {
            out[i * N * N + j * N + k] = c.c0 * in_s[threadIdx.z][threadIdx.y][threadIdx.x]
                                       + c.c1 * in_s[threadIdx.z][threadIdx.y][threadIdx.x - 1]
                                       + c.c2 * in_s[threadIdx.z][threadIdx.y][threadIdx.x + 1]
                                       + c.c3 * in_s[threadIdx.z][threadIdx.y - 1][threadIdx.x]
                                       + c.c4 * in_s[threadIdx.z][threadIdx.y + 1][threadIdx.x]
                                       + c.c5 * in_s[threadIdx.z - 1][threadIdx.y][threadIdx.x]
                                       + c.c6 * in_s[threadIdx.z + 1][threadIdx.y][threadIdx.x];
        }
    }
}

void launchStencilTiledCube(const float* in, float* out, unsigned int N, StencilCoeffs c) {
    dim3 dimBlock(CUBE_IN_TILE_DIM, CUBE_IN_TILE_DIM, CUBE_IN_TILE_DIM);
    unsigned int tiles = (N + CUBE_OUT_TILE_DIM - 1) / CUBE_OUT_TILE_DIM;   // one block per output tile
    dim3 dimGrid(tiles, tiles, tiles);
    stencilTiledCubeKernel<<<dimGrid, dimBlock>>>(in, out, N, c);
}
